  en:{photoTitle:'Search photos',photoSubtitle:'Experimental local search by description.',photoHowTitle:'How to use it',photoHowBody:'Choose up to 20 JPEG, PNG or WebP photos, then describe what you are looking for. The first search downloads about 320 MB of model files; if document search is already installed, less is needed. Photos and queries stay on this device. WebGPU and additional memory are required. Results are suggestions, not detailed image descriptions. Photos are forgotten when this window is closed.',photoSelect:'Choose photos',photoQueryPlaceholder:'Example: a dog on the beach',photoSearch:'Search photos',photoStop:'Stop',photoCount:'{count} photos selected',photoSelectError:'Choose up to 20 JPEG, PNG or WebP images, each at most 20 MB.',photoNeedFiles:'Choose at least one photo.',photoDownloading:'Downloading model: {file}',photoLoading:'Loading the image model…',photoIndexing:'Analyzing photo {done} of {total}…',photoSearching:'Searching photos…',photoDone:'Photos ranked by similarity. Check the images to confirm.',photoCancelled:'Search stopped.',photoGpuError:'Photo search requires a browser with WebGPU.',photoError:'Photo search failed: {error}'},
